"""
Pydantic schemas for the Compute service.

"""

from datetime import datetime
from enum import Enum
from typing import Any, Optional

from pydantic import BaseModel, ConfigDict, Field


class ProfileType(str, Enum):
    """Profile type enumeration."""

    GLOBAL = "global"
    TRY = "try"
    SAVE = "save"


class BuildStatus(str, Enum):
    """Build status enumeration."""

    QUEUED = "QUEUED"
    WORKING = "WORKING"
    SUCCESS = "SUCCESS"
    FAILURE = "FAILURE"
    TIMEOUT = "TIMEOUT"
    CANCELLED = "CANCELLED"


class BuildInfo(BaseModel):
    """Build information for save-mode profiles."""

    build_id: str = Field(..., alias="buildId")
    status: BuildStatus
    start_time: Optional[datetime] = Field(default=None, alias="startTime")
    finish_time: Optional[datetime] = Field(default=None, alias="finishTime")
    log_url: Optional[str] = Field(default=None, alias="logUrl")

    model_config = ConfigDict(populate_by_name=True)


class ComputeProfile(BaseModel):
    """Represents a compute profile."""

    slug: str = Field(..., description="Unique profile identifier")
    profile_type: Optional[ProfileType] = Field(default=ProfileType.GLOBAL, alias="profileType")
    base_image: Optional[str] = Field(default=None, alias="baseImage")
    image: Optional[str] = Field(default=None, description="Docker image to use")
    display_name: Optional[str] = Field(default=None, alias="displayName")
    plan: Optional[str] = None
    rate_dollar: Optional[float] = Field(default=None, alias="rateDollar")
    rate_time_frame: Optional[str] = Field(default=None, alias="rateTimeFrame")
    cluster_id: Optional[str] = Field(default=None, alias="clusterId")
    description: Optional[str] = None
    ide: str = Field(default="lab")
    has_capacity: bool = Field(default=True, alias="hasCapacity")

    # Spawner routing: "docker-vm" profiles are on-demand BMA instances;
    # everything else uses the legacy K8s server path.
    spawner_type: Optional[str] = Field(default=None, alias="spawnerType")
    catalog_selector: Optional[dict[str, Any]] = Field(default=None, alias="catalogSelector")

    # Resource configuration
    cpu_guarantee: Optional[float] = Field(default=None, alias="cpuGuarantee")
    cpu_limit: Optional[float] = Field(default=None, alias="cpuLimit")
    mem_guarantee: Optional[str] = Field(default=None, alias="memGuarantee")
    mem_limit: Optional[str] = Field(default=None, alias="memLimit")
    gpu: bool = Field(default=False)
    features: Optional[str] = None

    # Owner fields (for user-owned profiles)
    is_owner: bool = Field(default=False, alias="isOwner")
    owner_email: Optional[str] = Field(default=None, alias="ownerEmail")

    # Build info (for save-mode profiles)
    build_info: Optional[BuildInfo] = Field(default=None, alias="buildInfo")

    model_config = ConfigDict(populate_by_name=True)


class ProfileCreateRequest(BaseModel):
    """Request to create a new profile."""

    base_image: str = Field(..., alias="baseImage", description="Base Docker image (required)")
    display_name: Optional[str] = Field(default=None, alias="displayName")
    description: Optional[str] = None
    cpu_guarantee: Optional[float] = Field(default=None, alias="cpuGuarantee")
    cpu_limit: Optional[float] = Field(default=None, alias="cpuLimit")
    mem_guarantee: Optional[str] = Field(default=None, alias="memGuarantee")
    mem_limit: Optional[str] = Field(default=None, alias="memLimit")
    gpu: bool = Field(default=False)
    ide: str = Field(default="lab")
    features: Optional[str] = None

    model_config = ConfigDict(populate_by_name=True)


class ProfileCreateResponse(BaseModel):
    """Response from profile creation."""

    slug: str
    profile_type: ProfileType = Field(..., alias="profileType")
    base_image: str = Field(..., alias="baseImage")
    image: str
    ide: str = Field(default="lab")
    has_capacity: bool = Field(..., alias="hasCapacity")
    build_info: Optional[BuildInfo] = Field(default=None, alias="buildInfo")

    model_config = ConfigDict(populate_by_name=True)


class ProfileDeleteResponse(BaseModel):
    """Response from profile deletion."""

    slug: str
    deleted: bool

    model_config = ConfigDict(populate_by_name=True)


class BuildStatusResponse(BaseModel):
    """Response from build status check."""

    slug: str
    image: str
    has_capacity: bool = Field(..., alias="hasCapacity")
    build_info: BuildInfo = Field(..., alias="buildInfo")

    model_config = ConfigDict(populate_by_name=True)


# =============================================================================
# Server Schemas
# =============================================================================


class ResourceSpec(BaseModel):
    """Resource specification (CPU/Memory)."""

    guarantee: float
    limit: float


class ProfileResources(BaseModel):
    """Profile resource specifications."""

    cpu: ResourceSpec
    memory: ResourceSpec


class ProfilePricing(BaseModel):
    """Profile pricing information."""

    rate_dollar: float = Field(..., alias="rateDollar")
    rate_time_frame: str = Field(..., alias="rateTimeFrame")
    rate_ratio_offered: float = Field(default=1, alias="rateRatioOffered")
    is_free: bool = Field(default=False, alias="isFree")
    credit_cost_per_minute: float = Field(default=0, alias="creditCostPerMinute")

    model_config = ConfigDict(populate_by_name=True)


class ProfileDetails(BaseModel):
    """Detailed profile information from GET /profiles/:slug."""

    id: Optional[str] = Field(default=None, alias="_id")
    slug: str
    display_name: str = Field(..., alias="display_name")
    description: Optional[str] = None
    plan: Optional[str] = None
    rate_dollar: float = Field(default=0, alias="rateDollar")
    rate_time_frame: str = Field(default="min", alias="rateTimeFrame")
    visibility: str = Field(default="public")
    gpu: bool = Field(default=False)
    ide: str = Field(default="jupyterlab")
    cluster_id: Optional[str] = Field(default=None, alias="clusterId")
    has_capacity: bool = Field(default=True, alias="hasCapacity")
    spawner_type: Optional[str] = Field(default=None, alias="spawnerType")
    catalog_selector: Optional[dict[str, Any]] = Field(default=None, alias="catalogSelector")
    resources: Optional[ProfileResources] = None
    pricing: Optional[ProfilePricing] = None

    model_config = ConfigDict(populate_by_name=True)

    @property
    def is_bma(self) -> bool:
        """Whether this profile provisions an on-demand BMA instance."""
        return self.spawner_type == "docker-vm"


class SessionToken(BaseModel):
    """JupyterHub session token."""

    token: str
    id: str
    user: str
    scopes: list[str] = Field(default_factory=list)
    note: Optional[str] = None
    created: Optional[datetime] = None
    expires_at: Optional[datetime] = Field(default=None, alias="expires_at")

    model_config = ConfigDict(populate_by_name=True)


class SessionTokenResponse(BaseModel):
    """Response from session token endpoint."""

    cluster_id: str = Field(..., alias="clusterId")
    token: SessionToken

    model_config = ConfigDict(populate_by_name=True)


class ServerDetails(BaseModel):
    """Server details when running."""

    name: Optional[str] = None
    ready: bool = Field(default=False)
    pending: Optional[str] = None
    url: Optional[str] = None
    progress_url: Optional[str] = Field(default=None, alias="progress_url")
    started: Optional[datetime] = None
    last_activity: Optional[datetime] = Field(default=None, alias="last_activity")
    state: Optional[dict] = None
    user_options: Optional[dict] = Field(default=None, alias="user_options")

    model_config = ConfigDict(populate_by_name=True)


class UserInfo(BaseModel):
    """JupyterHub user information."""

    name: str
    admin: bool = Field(default=False)
    groups: list[str] = Field(default_factory=list)
    kind: str = Field(default="user")
    created: Optional[datetime] = None
    last_activity: Optional[datetime] = Field(default=None, alias="last_activity")
    servers: dict = Field(default_factory=dict)

    model_config = ConfigDict(populate_by_name=True)


class ServerStatus(BaseModel):
    """Server status response."""

    cluster_id: str = Field(..., alias="clusterId")
    server_running: bool = Field(default=False, alias="serverRunning")
    server_starting: bool = Field(default=False, alias="serverStarting")
    current_profile: Optional[str] = Field(default=None, alias="currentProfile")
    server_details: Optional[ServerDetails] = Field(default=None, alias="serverDetails")
    user_info: Optional[UserInfo] = Field(default=None, alias="userInfo")
    url: Optional[str] = None

    model_config = ConfigDict(populate_by_name=True)


class ServerStartResponse(BaseModel):
    """Response from server start."""

    message: str
    cluster_id: str = Field(..., alias="clusterId")
    profile: str
    status: str
    # Set when the profile routed to the BMA layer (docker-vm); the new
    # instance ID for tracking/SSH. None for legacy K8s servers.
    instance_id: Optional[str] = Field(default=None, alias="instanceId")

    model_config = ConfigDict(populate_by_name=True)


class ServerStopResponse(BaseModel):
    """Response from server stop."""

    message: str
    cluster_id: str = Field(..., alias="clusterId")
    status: str

    model_config = ConfigDict(populate_by_name=True)


# =========================================================================
# Compute Sessions
# =========================================================================


class SessionDeduction(BaseModel):
    """A single deduction entry within a compute session."""

    timestamp: Optional[datetime] = None
    usage_period_minutes: Optional[int] = Field(default=None, alias="usagePeriodMinutes")
    compute_hours_deducted: Optional[float] = Field(default=None, alias="computeHoursDeducted")
    credits_charged: Optional[float] = Field(default=None, alias="creditsCharged")
    profile_slug: Optional[str] = Field(default=None, alias="profileSlug")
    v_cpus: Optional[int] = Field(default=None, alias="vCpus")

    model_config = ConfigDict(populate_by_name=True)


class ComputeSession(BaseModel):
    """A compute session record."""

    id: Optional[str] = Field(default=None, alias="_id")
    email: Optional[str] = None
    profile_slug: Optional[str] = Field(default=None, alias="profileSlug")
    cluster_id: Optional[str] = Field(default=None, alias="clusterId")
    v_cpus: Optional[int] = Field(default=None, alias="vCpus")
    credit_rate_per_hour: Optional[float] = Field(default=None, alias="creditRatePerHour")
    status: Optional[str] = None
    session_type: Optional[str] = Field(default=None, alias="sessionType")
    start_time: Optional[datetime] = Field(default=None, alias="startTime")
    end_time: Optional[datetime] = Field(default=None, alias="endTime")
    total_minutes: Optional[float] = Field(default=None, alias="totalMinutes")
    total_compute_hours_deducted: Optional[float] = Field(
        default=None, alias="totalComputeHoursDeducted"
    )
    total_credits_charged: Optional[float] = Field(default=None, alias="totalCreditsCharged")
    settled: Optional[bool] = None
    created_at: Optional[datetime] = Field(default=None, alias="createdAt")
    updated_at: Optional[datetime] = Field(default=None, alias="updatedAt")

    model_config = ConfigDict(populate_by_name=True, extra="ignore")


class UsageByType(BaseModel):
    """Usage breakdown by compute type (cpu/gpu)."""

    session_count: int = Field(default=0, alias="sessionCount")
    total_hours: float = Field(default=0, alias="totalHours")
    credits_charged: float = Field(default=0, alias="creditsCharged")
    compute_hours_deducted: Optional[float] = Field(default=None, alias="computeHoursDeducted")

    model_config = ConfigDict(populate_by_name=True)


class DailyUsage(BaseModel):
    """Daily usage entry."""

    date: str
    total_hours: float = Field(default=0, alias="totalHours")
    credits_charged: float = Field(default=0, alias="creditsCharged")
    compute_hours_deducted: Optional[float] = Field(default=None, alias="computeHoursDeducted")
    profiles: list[str] = Field(default_factory=list)
    session_count: int = Field(default=0, alias="sessionCount")
    by_type: Optional[dict[str, UsageByType]] = Field(default=None, alias="byType")

    model_config = ConfigDict(populate_by_name=True)


class UsageSummary(BaseModel):
    """Aggregate usage summary."""

    total_hours: float = Field(default=0, alias="totalHours")
    total_credits_charged: float = Field(default=0, alias="totalCreditsCharged")
    total_compute_hours_deducted: float = Field(default=0, alias="totalComputeHoursDeducted")
    total_sessions: int = Field(default=0, alias="totalSessions")
    cpu_sessions: int = Field(default=0, alias="cpuSessions")
    gpu_sessions: int = Field(default=0, alias="gpuSessions")

    model_config = ConfigDict(populate_by_name=True)


class ComputeUsage(BaseModel):
    """Full usage response."""

    daily: list[DailyUsage] = Field(default_factory=list)
    summary: Optional[UsageSummary] = None
    compute_hours: Optional[dict[str, Any]] = Field(default=None, alias="computeHours")
    disk_usage: Optional[dict[str, Any]] = Field(default=None, alias="diskUsage")

    model_config = ConfigDict(populate_by_name=True)


# =========================================================================
# BMA Instances (on-demand PAYG compute)
# =========================================================================


class BMAStatus(str, Enum):
    """Lifecycle status of a BMA instance."""

    PROVISIONING = "provisioning"
    RUNNING = "running"
    STOPPING = "stopping"
    STOPPED = "stopped"
    TERMINATED = "terminated"
    ERROR = "error"


class BMAProgress(BaseModel):
    """Progress object emitted at each lifecycle stage to drive a spinner/bar."""

    phase: Optional[str] = (
        None  # e.g. queued|creating|booting|starting|ready|resuming|stopping|error
    )
    percent: Optional[int] = None
    message: Optional[str] = None

    model_config = ConfigDict(populate_by_name=True)


class BMAInstance(BaseModel):
    """An on-demand BMA instance (docker-vm profile).

    Returned by the ``/compute/bma/instances`` routes. The BMA layer hides the
    underlying cloud vendor; the profile + specs are the user-facing identity.
    """

    instance_id: str = Field(..., alias="instanceId")
    status: BMAStatus
    profile_slug: Optional[str] = Field(default=None, alias="profileSlug")
    url: Optional[str] = None  # live only when status == "running"
    last_error: Optional[str] = Field(default=None, alias="lastError")  # GET-one only
    created_at: Optional[datetime] = Field(default=None, alias="createdAt")
    running_at: Optional[datetime] = Field(default=None, alias="runningAt")
    stopped_at: Optional[datetime] = Field(default=None, alias="stoppedAt")
    progress: Optional[BMAProgress] = None
    ready: bool = Field(default=False)  # true only when running AND lab answers
    pending: Optional[str] = None  # "spawn" | "stop" | None
    auto_stop_idle_minutes: Optional[int] = Field(default=None, alias="autoStopIdleMinutes")
    max_session_minutes: Optional[int] = Field(default=None, alias="maxSessionMinutes")
    running_credits_per_min: Optional[float] = Field(default=None, alias="runningCreditsPerMin")
    stopped_credits_per_min: Optional[float] = Field(default=None, alias="stoppedCreditsPerMin")

    model_config = ConfigDict(populate_by_name=True, extra="ignore")
